import numpy as np
from scirel.collisions import thermal_electron_momentum

p_te = thermal_electron_momentum(temperature_kev=250.0, restmkev=511.0)
assert type(p_te) is float
assert p_te == 0.9891782353111633
assert p_te == float(np.sqrt(2.0 * 250.0 / 511.0))
assert 0.0 < p_te < 1.0
assert p_te == thermal_electron_momentum(
    temperature_kev=np.float64(250.0), restmkev=np.array(511.0)
)
for container in ([250.0], (250.0,), np.array([250.0]), np.array([[250.0]])):
    try:
        thermal_electron_momentum(temperature_kev=container, restmkev=511.0)
    except ValueError as error:
        assert str(error) == 'temperature_kev must be a scalar'
    else:
        raise AssertionError('a non-scalar container must be rejected')
try:
    thermal_electron_momentum(temperature_kev=0.0, restmkev=511.0)
except ValueError as error:
    assert 'finite and positive' in str(error)
else:
    raise AssertionError('a non-positive temperature must be rejected')
# A finite pair whose closed form overflows: 2.0 * 1.0e308 is infinity.
large = thermal_electron_momentum(temperature_kev=1.0e307, restmkev=511.0)
assert np.isfinite(large)
try:
    thermal_electron_momentum(temperature_kev=1.0e308, restmkev=511.0)
except ValueError as error:
    assert 'not representable' in str(error)
else:
    raise AssertionError('an unrepresentable closed form must be rejected')
